#!/bin/bash
function identify_fruit {
    local color=$1
    case $color in
        red)
            echo "Apple"
            ;;
        yellow)
            echo "Banana"
            ;;
        green)
            echo "Kiwi"
            ;;
        *)
            echo ""
            ;;
    esac
}

fruit=$(identify_fruit "orange")
if [ -z "$fruit" ]; then
    echo "No default case for identifying the fruit."
fi

